<div class="admin-panel stock-filters"><form class="stock-filter-bar" method="get"><input type="hidden" name="page" value="admin"><input type="hidden" name="section" value="stock"><label>Search<input class="form-control" name="search" value="<?= e($filters['search']) ?>" placeholder="Search by Part No., Name or Brand..."></label><label>Category<select class="form-select" name="category"><option value="">All Categories</option><?php foreach($categories as $category): ?><option value="<?= e((string)$category) ?>" <?= $filters['category']===$category?'selected':'' ?>><?= e((string)$category) ?></option><?php endforeach; ?></select></label><label>Brand<select class="form-select" name="brand"><option value="">All Brands</option><?php foreach($brands as $brand): ?><option value="<?= e((string)$brand) ?>" <?= $filters['brand']===$brand?'selected':'' ?>><?= e((string)$brand) ?></option><?php endforeach; ?></select></label><label>Stock Status<select class="form-select" name="status"><option value="">All Status</option><option value="in" <?= $filters['status']==='in'?'selected':'' ?>>In Stock</option><option value="low" <?= $filters['status']==='low'?'selected':'' ?>>Low Stock</option><option value="out" <?= $filters['status']==='out'?'selected':'' ?>>Out of Stock</option></select></label><div class="stock-filter-actions"><a class="btn btn-light" href="index.php?page=admin&amp;section=stock">Reset</a><button class="btn btn-danger" type="submit">Apply Filters</button></div></form></div>
<div class="admin-panel stock-list"><div class="panel-heading"><h2>Stock / Parts List</h2><span class="text-muted"><?= count($rows) ?> items</span></div><div class="table-responsive"><table class="table admin-table stock-table"><thead><tr><th>#</th><th>Part No.</th><th>Part Name</th><th>Category</th><th>Brand</th><th>Unit</th><th>Average Cost</th><th>Selling Price</th><th>Stock Qty</th><th>Min. Level</th><th>Status</th><th>Total Value</th><th>Action</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="13" class="empty-table">No stock items found. Click Add New Item to create the first item.</td></tr><?php else: foreach($rows as $index=>$row): $stockStatus=(float)$row['stock_qty']<=0?'out':((float)$row['stock_qty']<=(float)$row['reorder_level']?'low':'in');$statusText=$stockStatus==='out'?'Out of Stock':($stockStatus==='low'?'Low Stock':'In Stock'); ?><tr><td><?= $index+1 ?></td><td><?= e($row['part_code']) ?></td><td><strong><?= e($row['part_name']) ?></strong></td><td><?= e($row['category']?:'-') ?></td><td><?= e($row['brand']?:'-') ?></td><td><?= e($row['unit']) ?></td><td><?= number_format((float)$row['average_cost'],2) ?></td><td><?= number_format((float)$row['selling_price'],2) ?></td><td><strong><?= number_format((float)$row['stock_qty'],2) ?></strong></td><td><?= number_format((float)$row['reorder_level'],2) ?></td><td><span class="stock-status stock-status-<?= $stockStatus ?>"><?= $statusText ?></span></td><td><?= number_format((float)$row['stock_qty']*(float)$row['average_cost'],2) ?></td><td><div class="action-links employee-actions"><a href="index.php?page=admin&amp;section=stock-view&amp;id=<?= (int)$row['id'] ?>" title="View stock" aria-label="View stock">&#128065;</a><a href="index.php?page=admin&amp;section=stock-edit&amp;id=<?= (int)$row['id'] ?>" title="Edit stock" aria-label="Edit stock">&#9998;</a><form method="post" action="index.php?page=admin&amp;section=stock-delete" onsubmit="return confirm('Mark this stock item inactive?');"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="stock_id" value="<?= (int)$row['id'] ?>"><button type="submit" title="Remove stock" aria-label="Remove stock">&#128465;</button></form></div></td></tr><?php endforeach; endif; ?></tbody></table></div></div>
<div class="page-heading"><div><div class="breadcrumb-line">Home <span>&rsaquo;</span> Stock / Parts <span>&rsaquo;</span> <b><?= $section==='stock-low'?'Low Stock':'Stock List' ?></b></div><h1><?= e($title) ?></h1><p>Manage and track all stock items and parts.</p></div><div class="estimate-heading-actions"><a class="btn btn-light" href="index.php?page=admin&amp;section=stock-purchases">Stock Purchases</a><a class="btn btn-light" href="index.php?page=admin&amp;section=stock-restock">+ Restock Item</a><a class="btn btn-danger" href="index.php?page=admin&amp;section=stock-add">+ Add New Item</a></div></div><div class="admin-panel stock-list"><div class="panel-heading"><h2><?= $section==='stock-low'?'Low Stock Items':'Stock / Parts List' ?></h2><span><?= count($rows) ?> items</span></div><div class="table-responsive"><table class="table admin-table"><thead><tr><th>Part No.</th><th>Part Name</th><th>Category</th><th>Brand</th><th>Unit</th><th>Average Cost</th><th>Selling Price</th><th>Stock Qty</th><th>Min. Level</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="11" class="empty-table">No stock items found.</td></tr><?php else: foreach($rows as $row): $status=(float)$row['stock_qty']<=0?'Out of Stock':((float)$row['stock_qty']<=(float)$row['reorder_level']?'Low Stock':'In Stock'); ?><tr><td><?= e($row['part_code']) ?></td><td><strong><?= e($row['part_name']) ?></strong></td><td><?= e($row['category']?:'-') ?></td><td><?= e($row['brand']?:'-') ?></td><td><?= e($row['unit']) ?></td><td><?= number_format((float)($row['average_cost']?:$row['buying_price']),2) ?></td><td><?= number_format((float)$row['selling_price'],2) ?></td><td><strong><?= number_format((float)$row['stock_qty'],2) ?></strong></td><td><?= number_format((float)$row['reorder_level'],2) ?></td><td><span class="stock-status"><?= e($status) ?></span></td><td><div class="action-links employee-actions"><a href="index.php?page=admin&amp;section=stock-view&amp;id=<?= (int)$row['id'] ?>" title="View">&#128065;</a><a href="index.php?page=admin&amp;section=stock-restock&amp;id=<?= (int)$row['id'] ?>" title="Restock">+</a><form method="post" action="index.php?page=admin&amp;section=stock-delete&amp;id=<?= (int)$row['id'] ?>" onsubmit="return confirm('Remove this stock item?');"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><button type="submit" title="Delete">&#128465;</button></form></div></td></tr><?php endforeach; endif; ?></tbody></table></div></div>
